import os

# Создаем папки
dirs = [
    'src/app/login', 'src/app/register', 'src/app/profile',
    'src/app/students/[id]/edit', 'src/app/students/new',
    'src/app/students/components', 'src/app/api/auth/login',
    'src/app/api/auth/register', 'src/app/api/auth/logout',
    'src/components', 'public'
]
for d in dirs:
    os.makedirs(d, exist_ok=True)

# Содержимое файлов
files = {
    'package.json': '{\n  "name": "frontend",\n  "version": "0.1.0",\n  "private": true,\n  "scripts": {\n    "dev": "next dev",\n    "build": "next build",\n    "start": "next start"\n  },\n  "dependencies": {\n    "js-cookie": "^3.0.5",\n    "next": "16.4.5",\n    "react": "^19.0.0",\n    "react-dom": "^19.0.0"\n  }\n}',
    'next.config.mjs': "const nextConfig = { output: 'standalone' };\nexport default nextConfig;",
    'Dockerfile': 'FROM node:20-alpine AS deps\nWORKDIR /app\nCOPY package*.json ./\nRUN npm ci\n\nFROM node:20-alpine AS builder\nWORKDIR /app\nCOPY --from=deps /app/node_modules ./node_modules\nCOPY . .\nENV NEXT_TELEMETRY_DISABLED=1\nRUN mkdir -p public\nRUN npm run build\n\nFROM node:20-alpine AS runner\nWORKDIR /app\nENV NODE_ENV=production\nCOPY --from=builder /app/public ./public\nCOPY --from=builder /app/.next/standalone ./\nCOPY --from=builder /app/.next/static ./.next/static\nEXPOSE 3000\nENV PORT=3000\nCMD ["node", "server.js"]',
    '.dockerignore': "node_modules\n.next\n.git\n.env*",
    'src/app/layout.js': 'import "./globals.css";\nimport Link from "next/link";\nimport { cookies } from "next/headers";\nimport LogoutButton from "@/components/LogoutButton";\n\nexport const metadata = { title: "Управление студентами" };\n\nexport default async function RootLayout({ children }) {\n  const cookieStore = await cookies();\n  const token = cookieStore.get("accessToken")?.value;\n  return (\n    <html lang="ru">\n      <body>\n        <header style={{ maxWidth: "1100px", margin: "0 auto 25px" }}>\n          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: "15px" }}>\n            <Link href="/" style={{ textDecoration: "none", color: "inherit" }}><h1>Управление студентами</h1></Link>\n            <nav style={{ display: "flex", gap: "15px", alignItems: "center" }}>\n              {token ? (\n                <>\n                  <Link href="/students" style={{ fontWeight: "500", color: "#35548e" }}>Студенты</Link>\n                  <Link href="/profile" style={{ fontWeight: "500", color: "#35548e" }}>Профиль</Link>\n                  <LogoutButton />\n                </>\n              ) : (\n                <>\n                  <Link href="/login" style={{ fontWeight: "500", color: "#35548e" }}>Вход</Link>\n                  <Link href="/register" style={{ fontWeight: "500", color: "#35548e" }}>Регистрация</Link>\n                </>\n              )}\n            </nav>\n          </div>\n        </header>\n        <main>{children}</main>\n      </body>\n    </html>\n  );\n}',
    'src/app/page.js': "import { redirect } from 'next/navigation';\nexport default function Home() { redirect('/students'); }",
    'src/app/not-found.js': 'import Link from "next/link";\nexport default function NotFound() { return <section className="card"><h1>404 · Страница не найдена</h1><Link href="/students">К списку студентов</Link></section>; }',
    'src/components/LogoutButton.js': '"use client";\nimport { useRouter } from "next/navigation";\nexport default function LogoutButton() {\n  const router = useRouter();\n  const handleLogout = async () => {\n    await fetch("/api/auth/logout", { method: "POST" });\n    router.push("/login");\n    router.refresh();\n  };\n  return <button onClick={handleLogout} className="button ghost">Выйти</button>;\n}',
    'src/app/api/auth/login/route.js': 'import { NextResponse } from "next/server";\nexport async function POST(request) {\n  const body = await request.json();\n  const res = await fetch("http://localhost:8000/api/auth/login", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });\n  const data = await res.json();\n  if (!res.ok) return NextResponse.json(data, { status: res.status });\n  const response = NextResponse.json({ success: true });\n  response.cookies.set("accessToken", data.accessToken, { httpOnly: true, maxAge: data.expiresIn, path: "/" });\n  response.cookies.set("refreshToken", data.refreshToken, { httpOnly: true, maxAge: 60 * 60 * 24 * 7, path: "/" });\n  response.cookies.set("role", data.role, { maxAge: 60 * 60 * 24 * 7, path: "/" });\n  return response;\n}',
    'src/app/api/auth/register/route.js': 'import { NextResponse } from "next/server";\nexport async function POST(request) {\n  const body = await request.json();\n  const res = await fetch("http://localhost:8000/api/auth/register", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });\n  const data = await res.json();\n  if (!res.ok) return NextResponse.json(data, { status: res.status });\n  const response = NextResponse.json({ success: true });\n  response.cookies.set("accessToken", data.accessToken, { httpOnly: true, maxAge: data.expiresIn, path: "/" });\n  response.cookies.set("refreshToken", data.refreshToken, { httpOnly: true, maxAge: 60 * 60 * 24 * 7, path: "/" });\n  response.cookies.set("role", data.role, { maxAge: 60 * 60 * 24 * 7, path: "/" });\n  return response;\n}',
    'src/app/api/auth/logout/route.js': 'import { NextResponse } from "next/server";\nexport async function POST() {\n  const response = NextResponse.json({ success: true });\n  response.cookies.delete("accessToken");\n  response.cookies.delete("refreshToken");\n  response.cookies.delete("role");\n  return response;\n}',
    'src/app/login/page.js': '"use client";\nimport { useState } from "react";\nimport { useRouter } from "next/navigation";\nimport Link from "next/link";\nexport default function LoginPage() {\n  const router = useRouter();\n  const [username, setUsername] = useState("");\n  const [password, setPassword] = useState("");\n  const [error, setError] = useState(null);\n  const [busy, setBusy] = useState(false);\n  const handleSubmit = async (e) => {\n    e.preventDefault(); setBusy(true); setError(null);\n    try {\n      const res = await fetch("/api/auth/login", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ username, password }) });\n      const data = await res.json();\n      if (!res.ok) throw new Error(data.error || "Ошибка входа");\n      router.push("/students"); router.refresh();\n    } catch (err) { setError(err.message); } finally { setBusy(false); }\n  };\n  return (\n    <div className="auth-layout"><section className="card auth-card"><h2>Вход</h2>\n      {error && <div className="alert error">{error}</div>}\n      <form onSubmit={handleSubmit} aria-busy={busy}>\n        <div className="field"><label>Имя пользователя</label><input type="text" value={username} onChange={e => setUsername(e.target.value)} disabled={busy} required /></div>\n        <div className="field"><label>Пароль</label><input type="password" value={password} onChange={e => setPassword(e.target.value)} disabled={busy} required /></div>\n        <button className="primary full" disabled={busy}>{busy ? "Подождите…" : "Войти"}</button>\n      </form>\n      <p className="auth-switch">Нет аккаунта? <Link href="/register">Зарегистрироваться</Link></p>\n    </section></div>\n  );\n}',
    'src/app/register/page.js': '"use client";\nimport { useState } from "react";\nimport { useRouter } from "next/navigation";\nimport Link from "next/link";\nexport default function RegisterPage() {\n  const router = useRouter();\n  const [form, setForm] = useState({ username: "", email: "", password: "" });\n  const [error, setError] = useState(null);\n  const [busy, setBusy] = useState(false);\n  const handleSubmit = async (e) => {\n    e.preventDefault(); setBusy(true); setError(null);\n    try {\n      const res = await fetch("/api/auth/register", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(form) });\n      const data = await res.json();\n      if (!res.ok) {\n        let errorMessage = data.error || "Ошибка регистрации";\n        if (data.detail && typeof data.detail === "object") {\n          const firstError = Object.values(data.detail)[0]; if (firstError) errorMessage = firstError;\n        }\n        throw new Error(errorMessage);\n      }\n      router.push("/students"); router.refresh();\n    } catch (err) { setError(err.message); } finally { setBusy(false); }\n  };\n  return (\n    <div className="auth-layout"><section className="card auth-card"><h2>Регистрация</h2>\n      {error && <div className="alert error" style={{ whiteSpace: "pre-line" }}>{error}</div>}\n      <form onSubmit={handleSubmit} aria-busy={busy}>\n        <div className="field"><label>Имя пользователя</label><input type="text" required minLength={3} maxLength={50} value={form.username} onChange={e => setForm({...form, username: e.target.value})} disabled={busy} /></div>\n        <div className="field"><label>Email</label><input type="email" required maxLength={254} value={form.email} onChange={e => setForm({...form, email: e.target.value})} disabled={busy} /></div>\n        <div className="field"><label>Пароль (мин. 8 символов)</label><input type="password" required minLength={8} maxLength={72} value={form.password} onChange={e => setForm({...form, password: e.target.value})} disabled={busy} /></div>\n        <button className="primary full" disabled={busy}>{busy ? "Подождите…" : "Создать аккаунт"}</button>\n      </form>\n      <p className="auth-switch">Уже есть аккаунт? <Link href="/login">Войти</Link></p>\n    </section></div>\n  );\n}',
    'src/app/profile/page.js': 'import { cookies } from "next/headers";\nimport { redirect } from "next/navigation";\nasync function fetchProfile(token) {\n  const res = await fetch("http://localhost:8000/api/auth/me", { headers: { Authorization: `Bearer ${token}` }, cache: "no-store" });\n  if (!res.ok) return null;\n  return res.json();\n}\nexport default async function ProfilePage() {\n  const cookieStore = await cookies(); const token = cookieStore.get("accessToken")?.value;\n  if (!token) redirect("/login");\n  const profile = await fetchProfile(token);\n  if (!profile) return <div className="alert error">Не удалось загрузить профиль</div>;\n  return (\n    <section className="card narrow"><h1>Мой профиль</h1>\n      <dl className="details">\n        <dt>Имя пользователя</dt><dd>{profile.username}</dd>\n        <dt>Email</dt><dd>{profile.email}</dd>\n        <dt>Роль</dt><dd>{profile.role === "ADMIN" ? "Администратор" : "Пользователь"}</dd>\n        <dt>ID</dt><dd className="mono">{profile.id}</dd>\n      </dl>\n    </section>\n  );\n}',
    'src/app/students/loading.js': 'export default function Loading() { return <div className="card" style={{display:"flex",justifyContent:"center",padding:"40px"}}><p className="loading" role="status"><span className="spinner" /> Загрузка студентов…</p></div>; }',
    'src/app/students/error.js': '"use client";\nexport default function Error({ error, reset }) {\n  return <div className="card" style={{ textAlign: "center", padding: "40px" }}><h2>Что-то пошло не так!</h2><p className="muted" style={{ marginBottom: "20px" }}>{error.message}</p><button className="primary" onClick={() => reset()}>Попробовать снова</button></div>;\n}',
    'src/app/students/actions.js': '"use server";\nimport { cookies } from "next/headers";\nimport { revalidatePath } from "next/cache";\nimport { redirect } from "next/navigation";\nexport async function createStudentAction(formData) {\n  const cookieStore = await cookies(); const token = cookieStore.get("accessToken")?.value;\n  const data = { fullName: formData.get("fullName"), group: formData.get("group"), isuId: formData.get("isuId"), dormitory: Number(formData.get("dormitory")), room: Number(formData.get("room")), moveInDate: formData.get("moveInDate"), isForeigner: formData.get("isForeigner") === "on", notes: formData.get("notes") || "" };\n  const res = await fetch("http://localhost:8000/api/requests", { method: "POST", headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` }, body: JSON.stringify(data) });\n  if (!res.ok) throw new Error("Ошибка при создании");\n  revalidatePath("/students"); redirect("/students");\n}\nexport async function updateStudentAction(id, formData) {\n  const cookieStore = await cookies(); const token = cookieStore.get("accessToken")?.value;\n  const data = { fullName: formData.get("fullName"), group: formData.get("group"), isuId: formData.get("isuId"), dormitory: Number(formData.get("dormitory")), room: Number(formData.get("room")), moveInDate: formData.get("moveInDate"), isForeigner: formData.get("isForeigner") === "on", notes: formData.get("notes") || "" };\n  const res = await fetch(`http://localhost:8000/api/requests/${id}`, { method: "PUT", headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` }, body: JSON.stringify(data) });\n  if (!res.ok) throw new Error("Ошибка при обновлении");\n  revalidatePath("/students"); revalidatePath(`/students/${id}`); redirect(`/students/${id}`);\n}\nexport async function deleteStudentAction(id) {\n  const cookieStore = await cookies(); const token = cookieStore.get("accessToken")?.value;\n  const res = await fetch(`http://localhost:8000/api/requests/${id}`, { method: "DELETE", headers: { Authorization: `Bearer ${token}` } });\n  if (!res.ok) throw new Error("Ошибка удаления");\n  revalidatePath("/students"); redirect("/students");\n}',
    'src/app/students/components/StudentFilters.js': '"use client";\nimport { useRouter, useSearchParams, usePathname } from "next/navigation";\nimport { useState, useEffect } from "react";\nexport default function StudentFilters() {\n  const router = useRouter(); const pathname = usePathname(); const searchParams = useSearchParams();\n  const [search, setSearch] = useState(searchParams.get("search") || "");\n  const [group, setGroup] = useState(searchParams.get("group") || "");\n  const [isForeigner, setIsForeigner] = useState(searchParams.get("isForeigner") || "");\n  const updateURL = (key, value) => {\n    const params = new URLSearchParams(searchParams.toString());\n    if (value) params.set(key, value); else params.delete(key);\n    params.set("page", "0"); router.push(`${pathname}?${params.toString()}`);\n  };\n  useEffect(() => {\n    const timer = setTimeout(() => { if (search !== (searchParams.get("search") || "")) updateURL("search", search); }, 500);\n    return () => clearTimeout(timer);\n  }, [search]);\n  return (\n    <div className="toolbar">\n      <input type="search" placeholder="Поиск..." value={search} onChange={e => setSearch(e.target.value)} />\n      <input type="text" placeholder="Группа" value={group} onChange={e => setGroup(e.target.value)} onBlur={() => updateURL("group", group)} />\n      <select value={isForeigner} onChange={e => { setIsForeigner(e.target.value); updateURL("isForeigner", e.target.value); }}>\n        <option value="">Все студенты</option><option value="true">Иностранцы</option><option value="false">Не иностранцы</option>\n      </select>\n    </div>\n  );\n}',
    'src/app/students/page.js': 'import { cookies } from "next/headers";\nimport Link from "next/link";\nimport StudentFilters from "./components/StudentFilters";\nasync function fetchStudents(searchParams, token) {\n  const query = new URLSearchParams();\n  for (const [key, value] of Object.entries(searchParams)) { if (value) query.append(key, value); }\n  if (!query.has("page")) query.append("page", "0"); if (!query.has("size")) query.append("size", "10");\n  const res = await fetch(`http://localhost:8000/api/requests?${query.toString()}`, { headers: { Authorization: `Bearer ${token}` }, next: { tags: ["students"] } });\n  if (!res.ok) throw new Error("Ошибка загрузки");\n  return { data: await res.json(), total: res.headers.get("X-Total-Count") || "0", totalPages: res.headers.get("X-Total-Pages") || "1", currentPage: res.headers.get("X-Page") || "0" };\n}\nexport default async function StudentsPage({ searchParams }) {\n  const cookieStore = await cookies(); const token = cookieStore.get("accessToken")?.value; const role = cookieStore.get("role")?.value; const isAdmin = role === "ADMIN";\n  const params = await searchParams; let studentsData;\n  try { studentsData = await fetchStudents(params, token); } catch (error) { return <div className="alert error">Ошибка загрузки данных</div>; }\n  const { data: students, total, totalPages, currentPage } = studentsData;\n  const createPageLink = (newPage) => { const newParams = new URLSearchParams(params); newParams.set("page", newPage.toString()); return `/students?${newParams.toString()}`; };\n  return (\n    <section className="card">\n      <div className="toolbar" style={{ justifyContent: "space-between", paddingBottom: "10px" }}>\n        <h2>Список студентов</h2><span className="badge">Всего: {total}</span>\n        {isAdmin && <Link href="/students/new" className="btn-add">Добавить студента</Link>}\n      </div>\n      <StudentFilters />\n      {students.length > 0 ? (\n        <div className="table-wrapper"><table><thead><tr><th>ФИО</th><th>Группа</th><th>ИСУ ID</th><th>Общежитие</th><th>Комната</th><th>Дата заселения</th></tr></thead>\n          <tbody>{students.map(student => (<tr key={student.id}>\n            <td><Link href={`/students/${student.id}`}>{student.fullName}</Link></td><td>{student.group}</td><td>{student.isuId}</td><td>{student.dormitory}</td><td>{student.room}</td><td>{student.moveInDate?.split("-").reverse().join(".")}</td>\n          </tr>))}</tbody></table></div>\n      ) : (<p className="empty">Студенты не найдены.</p>)}\n      <div className="pagination"><div>\n        {Number(currentPage) > 0 ? <Link href={createPageLink(Number(currentPage) - 1)} className="button">← Назад</Link> : <button disabled>← Назад</button>}\n        <span>Страница {Number(currentPage) + 1} из {totalPages}</span>\n        {Number(currentPage) + 1 < Number(totalPages) ? <Link href={createPageLink(Number(currentPage) + 1)} className="button">Вперёд →</Link> : <button disabled>Вперёд →</button>}\n      </div></div>\n    </section>\n  );\n}',
    'src/app/students/[id]/page.js': 'import { cookies } from "next/headers";\nimport Link from "next/link";\nimport { notFound } from "next/navigation";\nimport { deleteStudentAction } from "../actions";\nasync function fetchStudent(id, token) {\n  const res = await fetch(`http://localhost:8000/api/requests/${id}`, { headers: { Authorization: `Bearer ${token}` }, next: { tags: [`student-${id}`] } });\n  if (res.status === 404) return null; if (!res.ok) throw new Error("Ошибка"); return res.json();\n}\nexport default async function StudentDetailPage({ params }) {\n  const cookieStore = await cookies(); const token = cookieStore.get("accessToken")?.value; const role = cookieStore.get("role")?.value; const isAdmin = role === "ADMIN";\n  const { id } = await params; const student = await fetchStudent(id, token); if (!student) notFound();\n  const deleteActionWithId = deleteStudentAction.bind(null, id);\n  return (<><Link className="back-link" href="/students">← К списку</Link><section className="card narrow"><h1>{student.fullName}</h1>\n    <dl className="details"><dt>Группа</dt><dd>{student.group}</dd><dt>ИСУ ID</dt><dd className="mono">{student.isuId}</dd><dt>Общежитие</dt><dd>{student.dormitory}</dd><dt>Комната</dt><dd>{student.room}</dd><dt>Дата заселения</dt><dd>{student.moveInDate?.split("-").reverse().join(".")}</dd><dt>Иностранец</dt><dd>{student.isForeigner ? "Да" : "Нет"}</dd><dt>Заметки</dt><dd className="preserve">{student.notes || "—"}</dd><dt>ID записи</dt><dd className="mono">{student.id}</dd></dl>\n    {isAdmin && (<div className="form-actions"><Link href={`/students/${id}/edit`} className="button primary">Редактировать</Link><form action={deleteActionWithId}><button type="submit" className="danger">Удалить</button></form></div>)}\n  </section></>);\n}',
    'src/app/students/new/page.js': 'import { createStudentAction } from "../actions";\nimport Link from "next/link";\nexport default function NewStudentPage() {\n  return (\n    <section className="card narrow"><h2>Добавить студента</h2>\n      <form action={createStudentAction} className="form-grid">\n        <div className="field"><label>ФИО *</label><input type="text" name="fullName" required maxLength={200} /></div>\n        <div className="field"><label>Группа *</label><input type="text" name="group" required maxLength={100} /></div>\n        <div className="field"><label>ИСУ ID *</label><input type="text" name="isuId" required pattern="[0-9]{6}" title="Ровно 6 цифр" /></div>\n        <div className="field"><label>Общежитие *</label><input type="number" name="dormitory" required min="1" /></div>\n        <div className="field"><label>Комната *</label><input type="number" name="room" required min="1" /></div>\n        <div className="field"><label>Дата заселения *</label><input type="date" name="moveInDate" required /></div>\n        <div className="field span-all"><label className="checkbox"><input type="checkbox" name="isForeigner" /> Иностранный студент</label></div>\n        <div className="field span-all"><label>Заметки</label><textarea name="notes" rows="4" maxLength={5000}></textarea></div>\n        <div className="form-actions span-all"><button type="submit" className="primary">Добавить</button><Link href="/students" className="button">Отмена</Link></div>\n      </form>\n    </section>\n  );\n}',
    'src/app/students/[id]/edit/page.js': 'import { cookies } from "next/headers";\nimport Link from "next/link";\nimport { updateStudentAction } from "../../actions";\nasync function fetchStudent(id, token) {\n  const res = await fetch(`http://localhost:8000/api/requests/${id}`, { headers: { Authorization: `Bearer ${token}` }, cache: "no-store" });\n  if (!res.ok) return null; return res.json();\n}\nexport default async function EditStudentPage({ params }) {\n  const cookieStore = await cookies(); const token = cookieStore.get("accessToken")?.value; const { id } = await params;\n  const student = await fetchStudent(id, token); if (!student) return <div className="alert error">Студент не найден</div>;\n  const updateActionWithId = updateStudentAction.bind(null, id);\n  return (\n    <section className="card narrow"><h2>Редактировать студента</h2>\n      <form action={updateActionWithId} className="form-grid">\n        <div className="field"><label>ФИО *</label><input type="text" name="fullName" required defaultValue={student.fullName} maxLength={200} /></div>\n        <div className="field"><label>Группа *</label><input type="text" name="group" required defaultValue={student.group} maxLength={100} /></div>\n        <div className="field"><label>ИСУ ID *</label><input type="text" name="isuId" required defaultValue={student.isuId} pattern="[0-9]{6}" title="Ровно 6 цифр" /></div>\n        <div className="field"><label>Общежитие *</label><input type="number" name="dormitory" required defaultValue={student.dormitory} min="1" /></div>\n        <div className="field"><label>Комната *</label><input type="number" name="room" required defaultValue={student.room} min="1" /></div>\n        <div className="field"><label>Дата заселения *</label><input type="date" name="moveInDate" required defaultValue={student.moveInDate} /></div>\n        <div className="field span-all"><label className="checkbox"><input type="checkbox" name="isForeigner" defaultChecked={student.isForeigner} /> Иностранный студент</label></div>\n        <div className="field span-all"><label>Заметки</label><textarea name="notes" rows="4" defaultValue={student.notes} maxLength={5000}></textarea></div>\n        <div className="form-actions span-all"><button type="submit" className="primary">Сохранить</button><Link href={`/students/${id}`} className="button">Отмена</Link></div>\n      </form>\n    </section>\n  );\n}',
    'src/proxy.js': 'import { NextResponse } from "next/server";\nexport function proxy(request) {\n  const token = request.cookies.get("accessToken")?.value; const role = request.cookies.get("role")?.value; const { pathname } = request.nextUrl;\n  const isProtected = pathname.startsWith("/students") || pathname === "/profile";\n  const isAdminRoute = pathname === "/students/new" || pathname.endsWith("/edit");\n  if (isProtected && !token) return NextResponse.redirect(new URL("/login", request.url));\n  if (isAdminRoute && role !== "ADMIN") return NextResponse.redirect(new URL("/students", request.url));\n  if ((pathname === "/login" || pathname === "/register") && token) return NextResponse.redirect(new URL("/students", request.url));\n  return NextResponse.next();\n}\nexport const config = { matcher: ["/students/:path*", "/profile", "/login", "/register"] };'
}

for path, content in files.items():
    with open(path, 'w', encoding='utf-8') as f:
        f.write(content)

print("SUCCESS: Vse faily vosstanovleny!")